**Input.tsx**
```tsx
import React, { useState, useEffect, useRef, useCallback, KeyboardEvent, ChangeEvent } from 'react';
import { FixedSizeList as List } from 'react-window';

// Define the component's props
interface AutocompleteInputProps {
  options: string[];
  placeholder?: string;
  onValueChange?: (value: string) => void;
  id?: string;
}

export const AutocompleteInput: React.FC<AutocompleteInputProps> = ({
  options,
  placeholder = 'Type to search...',
  onValueChange,
  id = 'autocomplete-input',
}) => {
  const [inputValue, setInputValue] = useState('');
  const [filteredOptions, setFilteredOptions] = useState<string[]>([]);
  const [isDropdownVisible, setDropdownVisible] = useState(false);
  const [activeIndex, setActiveIndex] = useState(-1);
  const [isInvalid, setInvalid] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const listRef = useRef<List>(null);

  // Filter options based on the input value
  useEffect(() => {
    if (inputValue.trim() === '') {
      setFilteredOptions([]);
      setDropdownVisible(false);
      return;
    }

    const lowercasedInput = inputValue.toLowerCase();
    const newFilteredOptions = options.filter(option =>
      option.toLowerCase().includes(lowercasedInput)
    );

    setFilteredOptions(newFilteredOptions);
    setDropdownVisible(newFilteredOptions.length > 0);
    setActiveIndex(-1); // Reset active index when the list changes
  }, [inputValue, options]);

  // Ensure the virtualized list scrolls to the highlighted item
  useEffect(() => {
    if (activeIndex >= 0 && listRef.current) {
      listRef.current.scrollToItem(activeIndex, 'smart');
    }
  }, [activeIndex]);

  // Handle clicks outside the component to close the dropdown
  const handleClickOutside = useCallback((event: MouseEvent) => {
    if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
      setDropdownVisible(false);
    }
  }, []);

  useEffect(() => {
    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [handleClickOutside]);

  // Handle input field changes
  const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setInputValue(value);
    onValueChange?.(value);
    setInvalid(false); // Reset validation state while user is typing
  };

  // Validate the input when it loses focus
  const handleBlur = () => {
    // A small timeout allows dropdown item clicks to register before the dropdown is hidden or validation runs
    setTimeout(() => {
      const isValid = options.some(opt => opt.toLowerCase() === inputValue.trim().toLowerCase());
      if (inputValue.trim() !== '' && !isValid) {
        setInvalid(true);
      } else {
        setInvalid(false);
      }
    }, 150);
  };

  // Handle keyboard navigation (Arrows, Enter, Escape)
  const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    if (!isDropdownVisible) return;

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        setActiveIndex(prev => (prev < filteredOptions.length - 1 ? prev + 1 : 0));
        break;
      case 'ArrowUp':
        e.preventDefault();
        setActiveIndex(prev => (prev > 0 ? prev - 1 : filteredOptions.length - 1));
        break;
      case 'Enter':
        e.preventDefault();
        if (activeIndex >= 0) {
          handleOptionSelect(filteredOptions[activeIndex]);
        }
        break;
      case 'Escape':
        setDropdownVisible(false);
        break;
    }
  };

  // Handle selecting an option via click or Enter key
  const handleOptionSelect = (option: string) => {
    setInputValue(option);
    onValueChange?.(option);
    setDropdownVisible(false);
    setInvalid(false);
    setActiveIndex(-1);
  };

  // --- Virtualized List Row Component ---
  const ITEM_HEIGHT = 35;
  const MAX_VISIBLE_ITEMS = 8;
  const dropdownHeight = Math.min(filteredOptions.length, MAX_VISIBLE_ITEMS) * ITEM_HEIGHT;

  const Row = ({ index, style }: { index: number; style: React.CSSProperties }) => (
    <div
      style={{
        ...style,
        display: 'flex',
        alignItems: 'center',
        padding: '0 10px',
        cursor: 'pointer',
        backgroundColor: index === activeIndex ? '#e0e0e0' : '#fff',
        fontWeight: index === activeIndex ? 'bold' : 'normal',
      }}
      onClick={() => handleOptionSelect(filteredOptions[index])}
      onMouseEnter={() => setActiveIndex(index)}
      role="option"
      aria-selected={index === activeIndex}
      id={`${id}-option-${index}`}
    >
      {filteredOptions[index]}
    </div>
  );

  return (
    <div ref={containerRef} style={{ position: 'relative', width: '300px' }}>
      <input
        id={id}
        type="text"
        value={inputValue}
        onChange={handleChange}
        onKeyDown={handleKeyDown}
        onFocus={() => isDropdownVisible || setDropdownVisible(filteredOptions.length > 0)}
        onBlur={handleBlur}
        placeholder={placeholder}
        style={{
          width: '100%',
          padding: '8px 12px',
          boxSizing: 'border-box',
          border: `2px solid ${isInvalid ? 'red' : '#ccc'}`,
          borderRadius: '4px',
        }}
        role="combobox"
        aria-autocomplete="list"
        aria-expanded={isDropdownVisible}
        aria-controls={`${id}-listbox`}
        aria-activedescendant={activeIndex >= 0 ? `${id}-option-${activeIndex}` : undefined}
      />
      {isDropdownVisible && (
        <div
          id={`${id}-listbox`}
          role="listbox"
          style={{
            position: 'absolute',
            top: 'calc(100% + 4px)',
            left: 0,
            right: 0,
            border: '1px solid #ccc',
            backgroundColor: 'white',
            zIndex: 100,
            maxHeight: `${dropdownHeight}px`,
            overflow: 'hidden',
            boxShadow: '0 4px 6px rgba(0,0,0,0.1)',
            borderRadius: '4px',
          }}
        >
          <List
            ref={listRef}
            height={dropdownHeight}
            itemCount={filteredOptions.length}
            itemSize={ITEM_HEIGHT}
            width="100%"
          >
            {Row}
          </List>
        </div>
      )}
    </div>
  );
};
```

