```zig
const std = @import("std");

/// Calculates (base^exp) % modulus using exponentiation by squaring.
/// This is efficient for large exponents.
fn modPow(base: u64, exp: u64, modulus: u64) u64 {
    var res: u64 = 1;
    var b = base % modulus;
    var e = exp;

    while (e > 0) {
        // If exponent is odd, multiply base with result
        if (e % 2 == 1) {
            // The intermediate product fits in u128, but for these specific numbers,
            // even u64 is sufficient as (modulus-1)^2 < u64.max.
            res = (@as(u128, res) * b) % modulus;
        }
        // e must be even now
        e >>= 1; // e = e / 2
        b = (@as(u128, b) * b) % modulus; // b = b^2 % modulus
    }
    return res;
}

/// Parses the first two unsigned 64-bit integers from a string.
fn parseRowAndCol(input: []const u8, allocator: std.mem.Allocator) !struct { row: u64, col: u64 } {
    var numbers: [2]u64 = undefined;
    var count: u8 = 0;

    var it = std.mem.tokenize(u8, input, " ,.()abcdefghijklmnopqrstuvwxyz-");
    while (it.next()) |token| {
        if (try std.fmt.parseInt(u64, token, 10)) |num| {
            if (count < 2) {
                numbers[count] = num;
                count += 1;
            } else {
                break;
            }
        }
    }

    if (count < 2) {
        return error.ParseError;
    }

    return .{ .row = numbers[0], .col = numbers[1] };
}

pub fn main() !void {
    const allocator = std.heap.page_allocator;
    const stdout = std.io.getStdOut().writer();

    // 1. Read input from file
    const input_bytes = try std.fs.cwd().readFileAlloc(allocator, "input.txt", 1024);
    defer allocator.free(input_bytes);

    // 2. Parse row and column
    const coords = try parseRowAndCol(input_bytes, allocator);
    const row = coords.row;
    const col = coords.col;

    // 3. Calculate the 1-indexed position 'n' in the sequence
    const diagonal_num = row + col - 1;
    const n = (diagonal_num * (diagonal_num - 1)) / 2 + col;

    // 4. Calculate the code using modular exponentiation
    const initial_code: u64 = 20151125;
    const multiplier: u64 = 252533;
    const modulus: u64 = 33554393;

    // The number of multiplications is n - 1
    const power = n - 1;

    const mult_pow = modPow(multiplier, power, modulus);
    const final_code = (@as(u128, initial_code) * mult_pow) % modulus;

