using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Windows.Forms;

namespace StudentDataApp
{
    /// <summary>
    /// Represents a single student with ID, Name, and GPA.
    /// </summary>
    public class Student
    {
        public int StudentID { get; set; }
        public string Name { get; set; }
        public decimal GPA { get; set; }

        /// <summary>
        /// Provides a string representation for display purposes.
        /// </summary>
        public override string ToString()
        {
            return $"ID: {StudentID}, Name: {Name}, GPA: {GPA:F2}";
        }
    }

    /// <summary>
    /// Handles reading and writing student data to a binary file.
    /// </summary>
    public static class StudentDB
    {
        // Define the directory and file path for the data file.
        private const string Dir = @"C:\C#\files\";
        private const string Path = Dir + "Students.dat";

        /// <summary>
        /// Saves a list of students to the binary file, overwriting any existing file.
        /// </summary>
        /// <param name="students">The list of students to save.</param>
        public static void SaveStudents(List<Student> students)
        {
            // Ensure the directory exists before writing.
            if (!Directory.Exists(Dir))
                Directory.CreateDirectory(Dir);

            // Use a BinaryWriter to write data. The 'using' statement ensures the stream is closed.
            using (BinaryWriter binaryOut = new BinaryWriter(
                new FileStream(Path, FileMode.Create, FileAccess.Write)))
            {
                foreach (Student student in students)
                {
                    binaryOut.Write(student.StudentID);
                    binaryOut.Write(student.Name);
                    binaryOut.Write(student.GPA);
                }
            }
        }

        /// <summary>
        /// Reads all students from the binary file.
        /// </summary>
        /// <returns>A list of students read from the file.</returns>
        public static List<Student> GetStudents()
        {
            List<Student> students = new List<Student>();

            // Ensure the directory exists before reading.
            if (!Directory.Exists(Dir))
                Directory.CreateDirectory(Dir);

            // If the file doesn't exist, return an empty list.
            if (!File.Exists(Path))
                return students;

            // Use a BinaryReader to read data. The 'using' statement ensures the stream is closed.
            using (BinaryReader binaryIn = new BinaryReader(
                new FileStream(Path, FileMode.Open, FileAccess.Read)))
            {
                // Read until the end of the file is reached.
                while (binaryIn.BaseStream.Position < binaryIn.BaseStream.Length)
                {
                    Student student = new Student
                    {
                        StudentID = binaryIn.ReadInt32(),
                        Name = binaryIn.ReadString(),
                        GPA = binaryIn.ReadDecimal()
                    };
                    students.Add(student);
                }
            }
            return students;
        }
    }

    /// <summary>
    /// Provides static methods for validating user input.
    /// </summary>
    public static class Validator
    {
        public static string LineEnd { get; set; } = "\n";

        public static string IsPresent(string value, string name)
        {
            return string.IsNullOrWhiteSpace(value) ? $"{name} is a required field.{LineEnd}" : "";
        }

        public static string IsInt32(string value, string name)
        {
            return !int.TryParse(value, out _) ? $"{name} must be a valid integer.{LineEnd}" : "";
        }

        public static string IsDecimal(string value, string name)
        {
            return !decimal.TryParse(value, out _) ? $"{name} must be a valid decimal.{LineEnd}" : "";
        }

        public static string IsWithinRange(string value, string name, decimal min, decimal max)
        {
            if (decimal.TryParse(value, out decimal number))
            {
                if (number < min || number > max)
                {
                    return $"{name} must be between {min} and {max}.{LineEnd}";
                }
            }
            return "";
        }
    }

    /// <summary>
    /// The main form for the application.
    /// </summary>
    public class MainForm : Form
    {
        // UI Controls
        private TextBox txtStudentID, txtName, txtGPA;
        private Button btnWrite, btnRead;
        private ListBox lstDisplay;

        public MainForm()
        {
            InitializeComponent();
        }

        private void InitializeComponent()
        {
            // Form Properties
            this.Text = "Student Data Management";
            this.Size = new Size(400, 420);
            this.FormBorderStyle = FormBorderStyle.FixedSingle;
            this.StartPosition = FormStartPosition.CenterScreen;

            // Controls Initialization
            Label lblStudentID = new Label { Text = "Student ID:", Location = new Point(20, 23), Size = new Size(80, 20) };
            txtStudentID = new TextBox { Location = new Point(110, 20), Size = new Size(250, 20) };

            Label lblName = new Label { Text = "Name:", Location = new Point(20, 53), Size = new Size(80, 20) };
            txtName = new TextBox { Location = new Point(110, 50), Size = new Size(250, 20) };

            Label lblGPA = new Label { Text = "GPA:", Location = new Point(20, 83), Size = new Size(80, 20) };
            txtGPA = new TextBox { Location = new Point(110, 80), Size = new Size(250, 20) };

            btnWrite = new Button { Text = "Write Data", Location = new Point(110, 120), Size = new Size(120, 30) };
            btnRead = new Button { Text = "Read Data", Location = new Point(240, 120), Size = new Size(120, 30) };

            lstDisplay = new ListBox { Location = new Point(20, 170), Size = new Size(340, 180) };

            // Event Handlers
            btnWrite.Click += BtnWrite_Click;
            btnRead.Click += BtnRead_Click;

            // Add Controls to Form
            this.Controls.AddRange(new Control[] {
                lblStudentID, txtStudentID, lblName, txtName, lblGPA, txtGPA,
                btnWrite, btnRead, lstDisplay
            });
        }

        /// <summary>
        /// Handles the click event for the "Write Data" button.
        /// </summary>
        private void BtnWrite_Click(object sender, EventArgs e)
        {
            // 1. Validate user input
            string errorMsg = Validator.IsPresent(txtStudentID.Text, "Student ID")
                            + Validator.IsInt32(txtStudentID.Text, "Student ID")
                            + Validator.IsPresent(txtName.Text, "Name")
                            + Validator.IsPresent(txtGPA.Text, "GPA")
                            + Validator.IsDecimal(txtGPA.Text, "GPA")
                            + Validator.IsWithinRange(txtGPA.Text, "GPA", 0.0m, 4.0m);

            if (!string.IsNullOrEmpty(errorMsg))
            {
                MessageBox.Show(errorMsg, "Input Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                return;
            }

            // 2. Create Student object
            var newStudent = new Student
            {
                StudentID = int.Parse(txtStudentID.Text),
                Name = txtName.Text,
                GPA = decimal.Parse(txtGPA.Text)
            };

            try
            {
                // 3. Read existing students, add the new one, and save the updated list
                List<Student> students = StudentDB.GetStudents();
                students.Add(newStudent);
                StudentDB.SaveStudents(students);

                MessageBox.Show("Student data saved successfully.", "Success", MessageBoxButtons.OK, MessageBoxIcon.Information);

                // 4. Clear input fields
                txtStudentID.Clear();
                txtName.Clear();
                txtGPA.Clear();
                txtStudentID.Focus();
            }
            catch (Exception ex)
            {
                MessageBox.Show($"An error occurred while writing to the file: {ex.Message}", "File Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        /// <summary>
        /// Handles the click event for the "Read Data" button.
        /// </summary>
        private void BtnRead_Click(object sender, EventArgs e)
        {
            try
            {
                // 1. Get students from the data file
                List<Student> students = StudentDB.GetStudents();
                lstDisplay.Items.Clear();

                // 2. Populate the ListBox
                if (students.Count > 0)
                {
                    foreach (var student in students)
                    {
                        lstDisplay.Items.Add(student); // Uses the ToString() override
                    }
                }
                else
                {
                    lstDisplay.Items.Add("No student data found in the file.");
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"An error occurred while reading the file: {ex.Message}", "File Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }
    }

    /// <summary>
    /// The main entry point for the application.
    /// </summary>
    static class Program
    {
        [STAThread]
        static void Main()
        {
            Application.EnableVisualStyles();
            Application.SetCompatibleTextRenderingDefault(false);
            Application.Run(new MainForm());
        }
    }
}
