// Helper function to write a string value to a specified file path.
// This helps avoid repeating the file open/write/close logic.
void writeToFile(const std::string& path, const std::string& value) {
    // Create an output file stream object. The constructor opens the file.
    std::ofstream fs(path);
    // Check if the file was successfully opened.
    if (!fs.is_open()) {
        // If not, print an error message to the standard error stream.
        std::cerr << "ERROR: Could not open file " << path << std::endl;
        // Exit the function early.
        return;
    }
    // Write the provided string 'value' into the file.
    fs << value;
    // The file is automatically closed when the 'fs' object goes out of scope.
}

int main() {
    // --- STEP 1: EXPORT THE NECESSARY GPIO PINS ---
    // This tells the kernel to make the GPIO pins available for use in userspace
    // under /sys/class/gpio/. We need to export 6 pins in total.
    std::cout << "1. Exporting GPIO pins..." << std::endl;
    writeToFile("/sys/class/gpio/export", "17"); // Motor A, IN1
    writeToFile("/sys/class/gpio/export", "18"); // Motor A, IN2
    writeToFile("/sys/class/gpio/export", "27"); // Motor A, ENA
    writeToFile("/sys/class/gpio/export", "22"); // Motor B, IN3
    writeToFile("/sys/class/gpio/export", "23"); // Motor B, IN4
    writeToFile("/sys/class/gpio/export", "24"); // Motor B, ENB

    // It can take a moment for the system to create the device files.
    // A short delay helps prevent errors in the next step.
    sleep(1);

    // --- STEP 2: SET THE GPIO PIN DIRECTIONS TO 'out' ---
    // We are sending signals *out* from our device to the L298N motor driver.
    std::cout << "2. Setting GPIO directions to output..." << std::endl;
    writeToFile("/sys/class/gpio/gpio17/direction", "out");
    writeToFile("/sys/class/gpio/gpio18/direction", "out");
    writeToFile("/sys/class/gpio/gpio27/direction", "out");
    writeToFile("/sys/class/gpio/gpio22/direction", "out");
    writeToFile("/sys/class/gpio/gpio23/direction", "out");
    writeToFile("/sys/class/gpio/gpio24/direction", "out");

    // --- STEP 3: ENABLE THE MOTOR DRIVER CHANNELS ---
    // Set the ENA and ENB pins to HIGH (1) to allow the motors to run.
    // If these are LOW (0), the motors will not move.
    std::cout << "3. Enabling motors..." << std::endl;
    writeToFile("/sys/class/gpio/gpio27/value", "1"); // Enable Motor A channel.
    writeToFile("/sys/class/gpio/gpio24/value", "1"); // Enable Motor B channel.

    // --- STEP 4: SET MOTOR DIRECTIONS AND RUN ---
    // We will make Motor A go forward and Motor B go backward.
    // L298N Logic: (IN1=1, IN2=0) -> Forward; (IN1=0, IN2=1) -> Backward
    std::cout << "4. Running motors (A forward, B backward) for 3 seconds..." << std::endl;
    writeToFile("/sys/class/gpio/gpio17/value", "1"); // Motor A, IN1 HIGH
    writeToFile("/sys/class/gpio/gpio18/value", "0"); // Motor A, IN2 LOW
    writeToFile("/sys/class/gpio/gpio22/value", "0"); // Motor B, IN3 LOW
    writeToFile("/sys/class/gpio/gpio23/value", "1"); // Motor B, IN4 HIGH

    // Let the motors run for 3 seconds.
    sleep(3);

    // --- STEP 5: STOP THE MOTORS ---
    // Setting both input pins to LOW (0) will cause the motors to brake.
    std::cout << "5. Stopping motors..." << std::endl;
    writeToFile("/sys/class/gpio/gpio17/value", "0"); // Motor A, IN1 LOW
    writeToFile("/sys/class/gpio/gpio18/value", "0"); // Motor A, IN2 LOW
    writeToFile("/sys/class/gpio/gpio22/value", "0"); // Motor B, IN3 LOW
    writeToFile("/sys/class/gpio/gpio23/value", "0"); // Motor B, IN4 LOW

    // --- STEP 6: CLEANUP - UNEXPORT THE GPIO PINS ---
    // This is good practice to release the pins after the program is done.
    std::cout << "6. Unexporting GPIO pins..." << std::endl;
    writeToFile("/sys/class/gpio/unexport", "17");
    writeToFile("/sys/class/gpio/unexport", "18");
    writeToFile("/sys/class/gpio/unexport", "27");
    writeToFile("/sys/class/gpio/unexport", "22");
    writeToFile("/sys/class/gpio/unexport", "23");
    writeToFile("/sys/class/gpio/unexport", "24");

    std::cout << "Program finished." << std::endl;
    return 0; // Indicates the program ran successfully.
