/* Le conteneur principal. On lui donne une taille et la perspective. */
.carte {
  width: 250px; /* Définir une largeur et hauteur pour la carte */
  height: 250px;
  background-color: transparent; /* Le fond sera sur les faces, pas le conteneur */
  perspective: 1000px; /* Crée l'espace 3D pour la rotation */
  border: none; /* La bordure sera sur les faces */
}

/* Le conteneur interne qui va pivoter. Il contient les deux faces. */
