Отличная задача! Чтобы добавить кнопку рестарта в ваш код для игры "Понг" на Arduino, нужно выполнить два шага: подключить кнопку физически и добавить логику для ее обработки в код.

### Куда подключать кнопку: к плюсу или минусу?

Кнопку нужно подключить **между цифровым пином и "минусом" (GND)**.

**Схема подключения:**
1.  Один контакт кнопки подключаете к любому свободному цифровому пину Arduino (например, D2).
2.  Второй контакт этой же кнопки подключаете к пину **GND** (земля, "минус").

Мы будем использовать встроенный в Arduino подтягивающий резистор (`INPUT_PULLUP`). Это значит, что когда кнопка не нажата, на пине будет высокий уровень сигнала (HIGH). Когда вы нажимаете кнопку, она замыкает пин на землю (GND), и на пине появляется низкий уровень сигнала (LOW). Именно это состояние (LOW) мы и будем отслеживать в коде как нажатие.

---

### Модифицированный код с кнопкой рестарта

Я добавил в ваш код все необходимые изменения. Основные моменты:
1.  **`#define RESTART_PIN 2`**: Определяем, что кнопка подключена к пину D2.
2.  **`pinMode(RESTART_PIN, INPUT_PULLUP)`**: В функции `setup()` настраиваем пин кнопки.
3.  **`restartGame()`**: Создана отдельная функция для сброса всех игровых переменных в начальное состояние и перерисовки экрана. Это делает код чище.
4.  **Проверка в `loop()`**: В основном цикле добавлена проверка нажатия кнопки. Код включает простую защиту от "дребезга" контактов и ожидает, пока вы отпустите кнопку, чтобы не вызывать рестарт много раз подряд.

```cpp
#include <SPI.h>
#include <Wire.hh>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

// Определяем пин для кнопки рестарта
#define RESTART_PIN 2

#define JOYSTICK1_X A0
#define JOYSTICK1_Y A1
#define JOYSTICK2_X A2
#define JOYSTICK2_Y A3

const unsigned long PADDLE_RATE = 33;
const unsigned long BALL_RATE = 40;
const uint8_t PADDLE_HEIGHT = 8;
const uint8_t BALL_SIZE = 3;

#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 32

#define OLED_RESET 4
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

void drawCourt();
void restartGame(); // Объявляем функцию рестарта

uint8_t ball_x = 64, ball_y = 16;
int8_t ball_dir_x = 1, ball_dir_y = 1; // Тип изменен на int8_t для корректной работы с отрицательными значениями
unsigned long ball_update;

unsigned long paddle_update;
const uint8_t CPU_X = 12;
uint8_t cpu_y = 8;

const uint8_t PLAYER_X = 115;
uint8_t player_y = 8;

void setup() {
  // Настраиваем пин кнопки как вход с внутренним подтягивающим резистором
  pinMode(RESTART_PIN, INPUT_PULLUP);

  display.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  display.display();
  unsigned long start = millis();

  display.clearDisplay();
  drawCourt();

  while (millis() - start < 2000);

  display.display();

  ball_update = millis();
  paddle_update = ball_update;
}

void loop() {
  // Проверяем, нажата ли кнопка рестарта
  if (digitalRead(RESTART_PIN) == LOW) {
    delay(50); // Простая защита от дребезга контактов
    if (digitalRead(RESTART_PIN) == LOW) {
      restartGame();
      // Ждем, пока кнопка будет отпущена, чтобы избежать повторных рестартов
      while(digitalRead(RESTART_PIN) == LOW) {
        delay(10);
      }
    }
  }

  bool update = false;
  unsigned long time = millis();

  int joy1_x = analogRead(JOYSTICK1_X);
  int joy1_y = analogRead(JOYSTICK1_Y);
  int joy2_x = analogRead(JOYSTICK2_X);
  int joy2_y = analogRead(JOYSTICK2_Y);

  if (time > ball_update) {
      uint8_t new_x = ball_x + ball_dir_x;
      uint8_t new_y = ball_y + ball_dir_y;

      if (new_y == 0 || new_y == 31 - BALL_SIZE) {
          ball_dir_y = -ball_dir_y;
          new_y += ball_dir_y + ball_dir_y;
      }

      if (new_x == CPU_X && new_y >= cpu_y && new_y <= cpu_y + PADDLE_HEIGHT) {
          ball_dir_x = -ball_dir_x;
          new_x += ball_dir_x + ball_dir_x;
      }

      if (new_x == PLAYER_X && new_y >= player_y && new_y <= player_y + PADDLE_HEIGHT) {
          ball_dir_x = -ball_dir_x;
          new_x += ball_dir_x + ball_dir_x;
      }

      display.fillRect(ball_x, ball_y, BALL_SIZE, BALL_SIZE, BLACK);
      display.fillRect(new_x, new_y, BALL_SIZE, BALL_SIZE, WHITE);
      ball_x = new_x;
      ball_y = new_y;

      ball_update += BALL_RATE;

      update = true;
  }

  if (time > paddle_update) {
      paddle_update += PADDLE_RATE;

      display.drawFastVLine(CPU_X, cpu_y, PADDLE_HEIGHT, BLACK);
      if (joy1_y < 400) {
          cpu_y -= 1;
      }
      if (joy1_y > 600) {
          cpu_y += 1;
      }
      if (cpu_y < 1)
          cpu_y = 1;
      if (cpu_y + PADDLE_HEIGHT > 31)
          cpu_y = 31 - PADDLE_HEIGHT;
      display.drawFastVLine(CPU_X, cpu_y, PADDLE_HEIGHT, WHITE);

      display.drawFastVLine(PLAYER_X, player_y, PADDLE_HEIGHT, BLACK);
      if (joy2_y < 400) {
          player_y -= 1;
      }
      if (joy2_y > 600) {
          player_y += 1;
      }
      if (player_y < 1)
          player_y = 1;
      if (player_y + PADDLE_HEIGHT > 31)
          player_y = 31 - PADDLE_HEIGHT;
      display.drawFastVLine(PLAYER_X, player_y, PADDLE_HEIGHT, WHITE);

      update = true;
  }

  if (update)
      display.display();
}

void drawCourt() {
  display.drawRect(0, 0, 128, 32, WHITE);
}

// Функция для сброса игры в начальное состояние
void restartGame() {
  // Сбрасываем координаты и направление мяча
  ball_x = 64;
  ball_y = 16;
  ball_dir_x = 1;
  ball_dir_y = 1;

  // Сбрасываем координаты ракеток
  cpu_y = 8;
  player_y = 8;

  // Сбрасываем таймеры, чтобы избежать резкого движения после рестарта
  ball_update = millis();
  paddle_update = millis();

  // Очищаем экран и рисуем все заново
  display.clearDisplay();
  drawCourt();
  display.fillRect(ball_x, ball_y, BALL_SIZE, BALL_SIZE, WHITE);
  display.drawFastVLine(CPU_X, cpu_y, PADDLE_HEIGHT, WHITE);
  display.drawFastVLine(PLAYER_X, player_y, PADDLE_HEIGHT, WHITE);
  display.display();
}
```

