#include <iostream>
#include <vector>
#include <iomanip> // Required for setting output precision

/**
 * @brief Generates a vector of linearly spaced values.
 * @param start The starting value of the sequence.
 * @param end The ending value of the sequence.
 * @param num The number of samples to generate.
 * @return A vector containing the linearly spaced values.
 */
std::vector<double> linspace(double start, double end, int num) {
    std::vector<double> result;
    if (num <= 0) {
        return result;
    }
    if (num == 1) {
        result.push_back(start);
        return result;
    }

    result.resize(num);
    double step = (end - start) / (num - 1);
    for (int i = 0; i < num; ++i) {
        result[i] = start + i * step;
    }
    return result;
}

/**
 * @brief Performs linear interpolation for a single point.
 * @param x The point at which to evaluate the interpolated value.
 * @param x_pts The vector of x-coordinates of the data points (must be sorted).
 * @param y_pts The vector of y-coordinates of the data points.
 * @return The interpolated y-value at x.
