#include <iostream>
#include <vector>
#include <cmath>     // For std::floor
#include <iomanip>   // For std::fixed and std::setprecision

// Generates a vector of 'num_points' values linearly spaced between 'start' and 'end'.
std::vector<double> linspace(double start, double end, int num_points) {
    std::vector<double> result;
    if (num_points <= 0) {
        return result;
    }
    if (num_points == 1) {
        result.push_back(start);
        return result;
    }

    result.reserve(num_points);
    double step = (end - start) / (num_points - 1);
    for (int i = 0; i < num_points; ++i) {
        result.push_back(start + i * step);
    }
    return result;
}

// Performs linear interpolation for a point 'x_new'.
// This optimized version assumes the original x-coordinates are 0, 1, 2, ...
double interp1d_optimized(double x_new, const std::vector<double>& y_original) {
    size_t n = y_original.size();

    // Handle boundary conditions by clamping to the edge values.
    if (x_new <= 0.0) {
        return y_original.front();
    }
    if (x_new >= n - 1) {
        return y_original.back();
    }

    // Find the index of the lower bound of the interval.
    size_t i = static_cast<size_t>(std::floor(x_new));

    // Get the surrounding points.
    double y0 = y_original[i];
    double y1 = y_original[i+1];
    double x0 = static_cast<double>(i);

    // Apply the linear interpolation formula.
    // The term (x1 - x0) is always 1, simplifying the formula.
    return y0 + (y1 - y0) * (x_new - x0);
}

