      // We check if the number of lines is greater than what we want to show initially.
      if (event.nativeEvent.lines.length > initialNumberOfLines) {
        setIsTruncated(true);
      }
      // Mark measurement as complete to render the final component.
      setIsMeasured(true);
    },
    [initialNumberOfLines]
  );

  const toggleExpansion = () => {
    setIsExpanded(!isExpanded);
  };

  // To prevent a flash of unstyled/unmeasured content, we render nothing until measured.
  if (!isMeasured) {
