### Core Concepts of My Answer:
1.  **Robust Data Model (`TennisMatch`)**: An `ObservableObject` class that encapsulates all the state and logic for the match. This includes point scores, game scores, set scores, and a history of every point.
2.  **Enum-Driven Logic**: Uses Swift enums (`Player`, `Point`, `PointOutcome`) to represent state in a type-safe way. This makes the scoring logic clearer and less prone to errors (e.g., using `Point.forty` instead of the integer `3`).
3.  **Correct Tennis Scoring**: The logic correctly handles the progression from points to games (including deuce and advantage) and from games to sets. It also detects the end of the match.
4.  **Modular UI**: The user interface is broken down into smaller, reusable SwiftUI views (`ScoreboardView`, `PointEntryView`, `PointHistoryView`), which is a best practice for building maintainable SwiftUI apps.
5.  **User-Friendly Advanced Options**: The advanced point tracking is integrated directly into the main screen with a `Toggle` and a `Picker`, providing a seamless user experience without disruptive pop-ups or sheets for a simple selection.
6.  **Clear State Display**: The UI clearly separates the overall match score (sets), the current game score, and the point history log.

```swift
import SwiftUI

// MARK: - Data Models

// Enum for the type of point outcome in advanced mode
enum PointOutcome: String, CaseIterable, Identifiable {
    case winner = "Winner"
    case unforcedError = "Unforced Error"
    case forcedError = "Forced Error"
    case ace = "Ace"
    case returnWinner = "Return Winner"
    case serveWinner = "Serve Winner"

    var id: String { self.rawValue }
}

// Struct to hold the details of a single point
struct PointLog: Identifiable {
    let id = UUID()
    let winningPlayer: Player
    let outcome: PointOutcome
    let timestamp = Date()
}

// Enum to represent the two players
enum Player {
    case player1
    case player2

    var name: String {
        switch self {
        case .player1: return "Player 1"
        case .player2: return "Player 2"
        }
    }
}

// Represents the score within a single game (0, 15, 30, 40, Ad)
enum Point: Int, Comparable {
    case love = 0, fifteen, thirty, forty, advantage

    static func < (lhs: Point, rhs: Point) -> Bool {
        return lhs.rawValue < rhs.rawValue
    }

    var display: String {
        switch self {
        case .love: return "0"
        case .fifteen: return "15"
        case .thirty: return "30"
        case .forty: return "40"
        case .advantage: return "Ad"
        }
    }
}

// Main data model for the match, conforming to ObservableObject for SwiftUI
class TennisMatch: ObservableObject {
    @Published var player1Points: Point = .love
    @Published var player2Points: Point = .love

    @Published var setScores: [(p1: Int, p2: Int)] = [(0, 0)]
    @Published var currentSetIndex = 0

    @Published var pointHistory: [PointLog] = []
    @Published var isMatchOver = false
    @Published var winner: Player? = nil

    // MARK: - Scoring Logic

    func awardPoint(to player: Player, with outcome: PointOutcome) {
        guard !isMatchOver else { return }

        // Log the point if advanced tracking is on
        pointHistory.append(PointLog(winningPlayer: player, outcome: outcome))

        // Update score
        if player == .player1 {
            scorePointForPlayer(&player1Points, opponentPoints: &player2Points)
        } else {
            scorePointForPlayer(&player2Points, opponentPoints: &player1Points)
        }
    }

    private func scorePointForPlayer(_ playerPoints: inout Point, opponentPoints: inout Point) {
        switch playerPoints {
        case .love, .fifteen:
            playerPoints = Point(rawValue: playerPoints.rawValue + 1)!
        case .thirty:
            playerPoints = .forty
        case .forty:
            if opponentPoints == .forty {
                playerPoints = .advantage // Deuce -> Ad-in
            } else if opponentPoints == .advantage {
                opponentPoints = .forty // Ad-out -> Deuce
            } else {
                // Player wins the game
                awardGame(to: playerPoints == player1Points ? .player1 : .player2)
            }
        case .advantage:
            // Player wins the game
            awardGame(to: playerPoints == player1Points ? .player1 : .player2)
        }
    }

    private func awardGame(to player: Player) {
        if player == .player1 {
            setScores[currentSetIndex].p1 += 1
        } else {
            setScores[currentSetIndex].p2 += 1
        }

        // Reset points for new game
        player1Points = .love
        player2Points = .love

        checkForSetWin()
    }

    private func checkForSetWin() {
        let currentSet = setScores[currentSetIndex]
        var setWinner: Player? = nil

        // Standard set win logic (no tie-break for simplicity)
        if (currentSet.p1 >= 6 && currentSet.p1 >= currentSet.p2 + 2) {
            setWinner = .player1
        } else if (currentSet.p2 >= 6 && currentSet.p2 >= currentSet.p1 + 2) {
            setWinner = .player2
        }

        if setWinner != nil {
            checkForMatchWin()
        }
    }

    private func checkForMatchWin() {
        let p1SetsWon = setScores.filter { $0.p1 > $0.p2 }.count
        let p2SetsWon = setScores.filter { $0.p2 > $0.p1 }.count

        if p1SetsWon == 2 {
            self.winner = .player1
            self.isMatchOver = true
        } else if p2SetsWon == 2 {
            self.winner = .player2
            self.isMatchOver = true
        } else {
            // Start a new set if the match isn't over and we are not at the 3rd set yet
            if currentSetIndex < 2 {
                currentSetIndex += 1
                setScores.append((0, 0))
            }
        }
    }

    func resetMatch() {
        player1Points = .love
        player2Points = .love
        setScores = [(0, 0)]
        currentSetIndex = 0
        pointHistory = []
        isMatchOver = false
        winner = nil
    }

    // MARK: - Computed Properties for UI

    var gameScoreDisplay: String {
        if player1Points >= .forty && player2Points >= .forty {
            if player1Points == player2Points {
                return "Deuce"
            } else if player1Points == .advantage {
                return "Ad - Player 1"
            } else {
                return "Ad - Player 2"
            }
        }
        return "\(player1Points.display) - \(player2Points.display)"
    }
}

// MARK: - SwiftUI Views

