import SwiftUI

// MARK: - Data Models

// Enum for the advanced point tracking details
enum PointOutcome: String, CaseIterable, Identifiable {
    case winner = "Winner"
    case unforcedError = "Unforced Error"
    case forcedError = "Forced Error"
    case ace = "Ace"
    case returnWinner = "Return Winner"
    case serveWinner = "Serve Winner"

    var id: String { self.rawValue }
}

// Struct to log the details of each point played
struct PointLog: Identifiable {
    let id = UUID()
    let winningPlayer: Player
    let outcome: PointOutcome
    let timestamp = Date()
}

// Enum to represent the two players
enum Player {
    case player1
    case player2

    var name: String {
        switch self {
        case .player1: return "Player 1"
        case .player2: return "Player 2"
        }
    }
}

// MARK: - View Model

@MainActor
class MatchViewModel: ObservableObject {

    // MARK: - Published Properties
    @Published var setScores: [(p1: Int, p2: Int)] = [(0, 0)]
    @Published var currentGameScore: (p1: String, p2: String) = ("0", "0")
    @Published var pointLog: [PointLog] = []
    @Published var isMatchOver: Bool = false
    @Published var matchWinner: Player? = nil

    // MARK: - Internal State
    private var currentSetIndex = 0
    private var p1Points = 0
    private var p2Points = 0

    // MARK: - Public Methods

    /// Awards a point to a player and updates the match state.
    func awardPoint(to player: Player, outcome: PointOutcome) {
        guard !isMatchOver else { return }

        // Log the point detail
        pointLog.append(PointLog(winningPlayer: player, outcome: outcome))

        // Update point score
        if player == .player1 {
            p1Points += 1
        } else {
            p2Points += 1
        }

        // Check for game, set, or match win
        checkForGameWin()
        updateGameScoreDisplay()
    }

    /// Resets the entire match to its initial state.
    func resetMatch() {
        setScores = [(0, 0)]
        currentGameScore = ("0", "0")
        pointLog = []
        isMatchOver = false
        matchWinner = nil
        currentSetIndex = 0
        p1Points = 0
        p2Points = 0
    }

    // MARK: - Private Logic

    private func checkForGameWin() {
        // A player wins a game if they have at least 4 points AND are ahead by at least 2 points.
        if (p1Points >= 4 && p1Points >= p2Points + 2) {
            awardGame(to: .player1)
        } else if (p2Points >= 4 && p2Points >= p1Points + 2) {
            awardGame(to: .player2)
        }
    }

    private func awardGame(to player: Player) {
        if player == .player1 {
            setScores[currentSetIndex].p1 += 1
        } else {
            setScores[currentSetIndex].p2 += 1
        }

        // Reset points for the new game
        p1Points = 0
        p2Points = 0

        checkForSetWin()
    }

    private func checkForSetWin() {
        let currentSet = setScores[currentSetIndex]
        let p1Games = currentSet.p1
        let p2Games = currentSet.p2

        // Note: This implementation does not include tie-breaks for simplicity.
        // A player wins a set if they have at least 6 games AND are ahead by at least 2 games.
        if (p1Games >= 6 && p1Games >= p2Games + 2) {
            awardSet(to: .player1)
        } else if (p2Games >= 6 && p2Games >= p1Games + 2) {
            awardSet(to: .player2)
        }
    }

    private func awardSet(to player: Player) {
        checkForMatchWin()

        // If match isn't over, start a new set
        if !isMatchOver && setScores.count < 3 {
            currentSetIndex += 1
            setScores.append((0, 0))
        }
    }

    private func checkForMatchWin() {
        let p1SetsWon = setScores.filter { $0.p1 > $0.p2 }.count
        let p2SetsWon = setScores.filter { $0.p2 > $0.p1 }.count

        // Best of 3 sets
        if p1SetsWon == 2 {
            isMatchOver = true
            matchWinner = .player1
        } else if p2SetsWon == 2 {
            isMatchOver = true
            matchWinner = .player2
        }
    }

    private func updateGameScoreDisplay() {
        // Handle Deuce and Advantage
        if p1Points >= 3 && p2Points >= 3 {
            if p1Points == p2Points {
                currentGameScore = ("Deuce", "Deuce")
            } else if p1Points > p2Points {
                currentGameScore = ("Ad", "40")
            } else {
                currentGameScore = ("40", "Ad")
            }
        } else {
            // Standard scoring
            currentGameScore.p1 = pointToString(p1Points)
            currentGameScore.p2 = pointToString(p2Points)
        }
    }

    private func pointToString(_ point: Int) -> String {
        switch point {
        case 0: return "0"
        case 1: return "15"
        case 2: return "30"
        case 3: return "40"
        default: return "" // Should not happen in standard play
        }
    }
}

