#### File 1: `AudioRecorderViewModel.swift`

This file contains the ViewModel, which encapsulates all the business logic for audio recording, permission handling, and state management. It communicates with the View via `@Published` properties.

```swift
import Foundation
import AVFoundation
import Combine

final class AudioRecorderViewModel: NSObject, ObservableObject {

    // MARK: - Published Properties
    @Published var isRecording = false
    @Published var audioPower: Float = 0.0
    @Published private(set) var recordedFileUrl: URL?

    // MARK: - Private Properties
    private var audioRecorder: AVAudioRecorder?
    private var powerMonitoringTimer: Timer?
    private var audioSession = AVAudioSession.sharedInstance()

    // MARK: - Public Methods

    func startRecording() {
        // Request permission and proceed only if granted
        audioSession.requestRecordPermission { [weak self] granted in
            guard let self = self else { return }

            guard granted else {
                print("Microphone permission was not granted.")
                // Here you would typically show an alert to the user.
                return
            }

            DispatchQueue.main.async {
                self.setupAndStartRecording()
            }
        }
    }

    func stopRecording() {
        audioRecorder?.stop()
        powerMonitoringTimer?.invalidate()

        do {
            try audioSession.setActive(false)
        } catch {
            print("Failed to deactivate audio session: \(error.localizedDescription)")
        }

        isRecording = false
    }

    // MARK: - Private Helper Methods

    private func setupAndStartRecording() {
        let recordingSettings: [String: Any] = [
            AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
            AVSampleRateKey: 44100,
            AVNumberOfChannelsKey: 1,
            AVEncoderAudioQualityKey: AVAudioQuality.high.rawValue
        ]

        let fileUrl = FileManager.default.temporaryDirectory.appendingPathComponent("\(UUID().uuidString).m4a")

        do {
            try audioSession.setCategory(.playAndRecord, mode: .default)
            try audioSession.setActive(true)

            audioRecorder = try AVAudioRecorder(url: fileUrl, settings: recordingSettings)
            audioRecorder?.delegate = self
            audioRecorder?.isMeteringEnabled = true
            audioRecorder?.record()

            isRecording = true
            startMonitoringPower()

        } catch {
            print("Failed to set up and start recording: \(error.localizedDescription)")
            isRecording = false
        }
    }

    private func startMonitoringPower() {
        powerMonitoringTimer = Timer.scheduledTimer(withTimeInterval: 0.1, repeats: true) { [weak self] _ in
            guard let self = self, let recorder = self.audioRecorder else { return }
            recorder.updateMeters()
            // The power is in dB, from -160 (silence) to 0 (max).
            // We'll normalize this for the UI.
            let peakPower = recorder.averagePower(forChannel: 0)
            self.audioPower = peakPower
        }
    }

    deinit {
        powerMonitoringTimer?.invalidate()
    }
}

// MARK: - AVAudioRecorderDelegate
extension AudioRecorderViewModel: AVAudioRecorderDelegate {
    func audioRecorderDidFinishRecording(_ recorder: AVAudioRecorder, successfully flag: Bool) {
        if flag {
            self.recordedFileUrl = recorder.url
            print("Recording finished successfully. Saved to: \(recorder.url.path)")
        } else {
            print("Recording failed to finish.")
            self.recordedFileUrl = nil
        }
    }
}
```

