import SwiftUI

struct EqualizerView: View {
    let power: Float // Expected range: -160 to 0 dB
    let isRecording: Bool

    private let barCount = 8

    private func normalizePower(_ power: Float) -> CGFloat {
        // Map the dB range (-60 to 0) to a 0-1 scale for UI height.
        // We clamp at -60dB as a reasonable "silence" threshold.
        let level = max(0, (power + 60) / 60)
        return CGFloat(level)
    }

    var body: some View {
        HStack(spacing: 4) {
            ForEach(0..<barCount, id: \.self) { _ in
                let heightMultiplier = normalizePower(power)
                // Add some randomness for a more dynamic "equalizer" feel
                let randomFactor = isRecording ? CGFloat.random(in: 0.7...1.0) : 0.0
                let barHeight = max(5, heightMultiplier * 100 * randomFactor)

                RoundedRectangle(cornerRadius: 2)
                    .fill(Color.blue)
                    .frame(width: 6, height: barHeight)
            }
        }
        .frame(height: 100, alignment: .center)
        .animation(.easeInOut(duration: 0.1), value: power)
    }
}
```

